insert into activities (id, title_th, date, location, description, featured, cover_id, status)
select (r->>'id')::uuid as id,
       nullif(r->>'title_th','') as title_th,
       nullif(r->>'date','')::date as date,
       nullif(r->>'location','') as location,
       nullif(r->>'description','') as description,
       coalesce(lower(r->>'featured') in ('yes','true','1'), false) as featured,
       nullif(r->>'cover_id','') as cover_id,
       coalesce(nullif(r->>'status',''),'draft')::content_status as status
